import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
import {chromium} from 'playwright-core';
const b=await chromium.connectOverCDP(process.env.TRADING_CDP_URL),p=b.contexts()[0].pages().find(p=>p.url().includes('/trading-proof'));const result=[];
try{await p.setViewportSize({width:1414,height:1000});for(const theme of ['light','dark']){await p.evaluate(t=>document.querySelector('[data-blast-ui]').setAttribute('data-theme',t),theme);await p.waitForTimeout(300);
const rows=await p.evaluate(()=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=1;const ctx=canvas.getContext('2d');const rgba=value=>{ctx.clearRect(0,0,1,1);ctx.fillStyle=value;ctx.fillRect(0,0,1,1);return [...ctx.getImageData(0,0,1,1).data].map((v,i)=>i===3?v/255:v);};const over=(a,b)=>[0,1,2].map(i=>a[i]*a[3]+b[i]*(1-a[3])).concat(1);const luminance=c=>c.slice(0,3).map(n=>n/255).map(n=>n<=.04045?n/12.92:((n+.055)/1.055)**2.4).reduce((v,n,i)=>v+n*[.2126,.7152,.0722][i],0);const selectors=['header dt','[data-workspace-section="activity"] button[aria-pressed="true"]','[data-workspace-section="activity"] button[aria-pressed="false"]','[class*="CoinPanel_side"][data-direction]','[data-coin-submit]','[data-workspace-section="details"] th','[data-workspace-section="details"] td[data-direction]','[data-workspace-section="details"] p','[class*="ActorCell_name"]'];return selectors.flatMap(selector=>[...document.querySelectorAll('[data-panel-id]:not([hidden]) '+selector)].filter(e=>e.checkVisibility()&&e.textContent.trim()&&!e.disabled).slice(0,8).map(e=>{let bg=[255,255,255,1];const ancestors=[];for(let n=e;n;n=n.parentElement)ancestors.push(n);for(const n of ancestors.reverse())bg=over(rgba(getComputedStyle(n).backgroundColor),bg);const foreground=over(rgba(getComputedStyle(e).color),bg),l1=luminance(foreground),l2=luminance(bg);return{selector,text:e.textContent.slice(0,50),foreground,bg,ratio:(Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05)};}));});result.push({theme,rows});}
writeFileSync(process.env.TRADING_EVIDENCE_DIR+'/contrast.json',JSON.stringify(result,null,2));const failures=result.flatMap(r=>r.rows.filter(x=>x.ratio<4.5).map(x=>({theme:r.theme,...x})));console.log(JSON.stringify({samples:result.reduce((n,r)=>n+r.rows.length,0),minimum:Math.min(...result.flatMap(r=>r.rows.map(x=>x.ratio))),failures},null,2));assert.equal(failures.length,0);
}finally{await b.close();}
